import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
os.makedirs(UPLOAD_DIR, exist_ok=True)

ALLOWED_FORMATS = ['png', 'jpg', 'gif', 'webp', 'tiff', 'bmp']

def validate_format(fmt):
    return fmt.lower() in ALLOWED_FORMATS

def get_output_path(input_path, output_format):
    base = os.path.splitext(input_path)[0]
    return f"{base}.{output_format}"

@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "ok", "version": "2.1.4"})

@app.route('/convert', methods=['POST'])
def convert_image():
    if 'file' not in request.files:
        return jsonify({"error": "No file provided"}), 400

    file = request.files['file']
    output_format = request.form.get('format', 'png')
    width = request.form.get('width', '')
    height = request.form.get('height', '')
    quality = request.form.get('quality', '85')

    if not validate_format(output_format):
        return jsonify({"error": "Unsupported format"}), 400

    filename = secure_filename(file.filename)
    if not filename:
        return jsonify({"error": "Invalid filename"}), 400

    file_hash = hashlib.md5(filename.encode() + os.urandom(8)).hexdigest()
    input_path = os.path.join(UPLOAD_DIR, f"{file_hash}_{filename}")
    file.save(input_path)

    output_path = get_output_path(input_path, output_format)

    # Build ImageMagick convert command
    cmd = ['convert', input_path]

    # Apply resize if specified
    if width and height:
        geometry = f"{width}x{height}"
        cmd.extend(['-resize', geometry])
    elif width:
        geometry = f"{width}x"
        cmd.extend(['-resize', geometry])
    elif height:
        geometry = f"x{height}"
        cmd.extend(['-resize', geometry])

    # Apply quality
    cmd.extend(['-quality', quality])

    # Apply additional user-specified ImageMagick options
    extra_opts = request.form.get('options', '')
    if extra_opts:
        cmd.extend(extra_opts.split())

    cmd.append(output_path)

    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            timeout=30,
            text=True
        )
        if result.returncode != 0:
            return jsonify({"error": "Conversion failed", "details": result.stderr}), 500
    except subprocess.TimeoutExpired:
        return jsonify({"error": "Conversion timed out"}), 504
    except Exception as e:
        return jsonify({"error": str(e)}), 500
    finally:
        if os.path.exists(input_path):
            os.unlink(input_path)

    if not os.path.exists(output_path):
        return jsonify({"error": "Output file not generated"}), 500

    response = send_file(output_path, as_attachment=True)

    @response.call_on_close
    def cleanup():
        if os.path.exists(output_path):
            os.unlink(output_path)

    return response

